/* 作者：栗子*/
/* 禁商禁二传 */
/* 可自用二改 */
/* 感谢各位美化老师们分享的代码*/
/* 气泡底素来源小红书：橘子写字文创，已获授权 */
/* 使用过商业美化或支持商业化的人不准用，我觉得特恶心 */
/*遇到问题请先在全局设置里自改，调字体大小直接滑动字体比例 */
/*如果你没有下载QR助手，但想把qr折叠，可以划到最后打开最后两段代码(去掉开头结尾的注释符)*/

@import url("https://fontsapi.zeoseven.com/79/main/result.css");/* 正文字体 Clear Han Serif */
@import url("https://fontsapi.zeoseven.com/970/main/result.css");/*名字诗句 XuanZongTi*/
@import url("https://fontsapi.zeoseven.com/491/main/result.css");/* 翻页 平方赖江湖飞扬体*/


/* == 全局设置 == */
:root {
    --topBarBlockSize: 27px; 
    --box-border-radius: 5px;
    --top-distance: 7px;
    --scroll-width: 4px;

/* == 名字大小和诗句自定义 == */
--名字大小:30px;
--诗句大小:25px;
--间距:5px;/*越小，诗句越靠近名字，可负数*/
--诗句: "草堂春睡足";

/* == 头像位置、大小、形状 == */
--头像上下:50px;
--头像左右:-25vw;
--倍数:0.8;
--圆角:50%;

/* == 调整消息元三要素位置== */
--楼层水平方向:59vw; 
--楼层垂直方向:-80px;
--token水平方向:45vw; 
--token垂直方向:-80px;
--时间水平方向:30vw; 
--时间垂直方向:-80px;  

/* == 气泡底素替换 == */
--气泡顶部:url('https://iili.io/BKTsrg4.jpg');
--气泡底部:url('https://iili.io/BKuTaYG.jpg');
}

body,
.text_pole:not(#completion_prompt_manager_list),
select,
textarea:not(#send_textarea),
input {
    font-family: "Clear Han Serif";
    font-weight: normal;
}

code,
code * {
    font-family: "Clear Han Serif" !important;
    font-weight: normal;
}

/* == 聊天主界面布局 == */
/* 二改自kakaa老师的双色盒子 */
#sheld {
    height: calc(100dvh - var(--topBarBlockSize));    
}
/*其他背景图*/
#left-nav-panel.drawer-content,
#user-settings-block.drawer-content,
#right-nav-panel.drawer-content,
#rm_extensions_block.drawer-content,
#PersonaManagement.drawer-content{
    background-repeat: no-repeat!important;
    background-size: cover!important;   
}
#left-nav-panel.drawer-content{background-image: url('https://iili.io/BCukc74.jpg');}
#user-settings-block.drawer-content{background-image: url('https://iili.io/BnBPqox.jpg');}
#rm_extensions_block.drawer-content{background-image: url('https://iili.io/BBbLye2.jpg');}
#PersonaManagement.drawer-content{background-image: url('https://iili.io/BBbLye2.jpg');}
#right-nav-panel.drawer-content{background-image: url('https://iili.io/BBbLDgf.jpg');}
#chat {
    background: transparent !important;
    background-color: transparent !important;
    backdrop-filter: none;
    border: none !important;
    overflow-y: scroll;
    align-items: center;
    max-height: calc(100dvh - var(--topBarBlockSize) - 20px) !important;
    margin-left:4px;
    border-radius: 0 0 var(--box-border-radius) var(--box-border-radius);
}

@supports (-webkit-touch-callout: none) {
    #chat {
        padding-right: var(--scroll-width);
    }
}

/*滚动条贴图学习了千尾老师*/
::-webkit-scrollbar {
    width: 4px;
}

::-webkit-scrollbar-track {
    background: transparent!important;
    padding: 0;
   border: none;
}
::-webkit-scrollbar-thumb{
  background-color: #6BB392 !important;
  background-repeat: no-repeat;
  background-position: center center;
  border: none !important;
  box-shadow: none !important;
  border-radius: 20px;}
::-webkit-scrollbar-thumb:vertical,
::-webkit-scrollbar-thumb:horizontal {
    background-color: #ffffff;
    box-shadow: none;
    border: 0;
}

/* == 消息气泡 == */
.mes {
  width: 98%;
  position: relative;
  min-height: auto;
  padding: 8px 10px;
  margin: 6.5rem auto 4.5rem auto;
  border-radius: 0px !important;
  border: 1px solid rgba(255, 255, 255, 0.15);
  display: flex;
  flex-direction: column;
  align-items: center; 
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.1);
}
.last_mes {
  margin-bottom: 6.5rem !important;
}

/* 底素来源小红书：橘子写字文创 */
/* 气泡背景装饰 */
.mes::before {
     content: "";
     position: absolute;     
     left: 0;
    top: -40px;
    width: 100%;    
    height: 300px;    
     background-image: var(--气泡顶部);
     background-size: cover;
     background-repeat: no-repeat;
     opacity: 1 !important;
     pointer-events: none; 
     -webkit-mask-image: linear-gradient(to bottom, black 70%, transparent 100%);
     mask-image: linear-gradient(to bottom, black 70%, transparent 100%);
}

.mes::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;
  width: 100%;    
  height:300px;    
  background-size: cover;
  background-repeat: no-repeat;
  opacity: 0.8 !important;
  pointer-events: none;
  mask: linear-gradient(to bottom, rgba(0,0,0,0), rgba(0,0,0,1) 70%);
  -webkit-mask: linear-gradient(to bottom, rgba(0,0,0,0), rgba(0,0,0,1) 70%);
    background-image: var(--气泡底部);
}

/* ==头像与名字 == */
.mesAvatarWrapper {
    position: relative;    
    top:50px;
    right:22%;
    transform: none !important;
    padding: 3px !important;    
    margin-bottom: 200px;
 }

 #chat .mes .avatar {
    position: absolute;
    display: inline-block;
    padding: 8px;
    top:var(--头像上下);
    left: var(--头像左右);
    opacity: 1!important;
    transform:scale(var(--倍数));
    z-index:999;
}

#chat .mes .avatar img {
    border-radius:var(--圆角);
    position:absolute;
    width:120px;
    height:120px;
    object-fit: cover;
    object-position:50% 40%;
    z-index:1; 
}

#quickPersona{
position:absolute;
left:0px;
opacity:1!important;
}

/* 头像选中框 */
.avatar-container.interactable.selected {
    border: 4px solid #FADE3D !important;
    border-radius: 0% !important;
    background: none !important;
    background-size: cover !important; 
}


/* ==消息内容与排版== */
.mes_block {
    width: 100%;
    padding-left: 0;
    padding-right: 0;
    z-index:999;
    position:relative;
    padding-top: 0px;
    padding-bottom: 100px;    
    overflow: visible;
}

.mes .name_text {
  position: relative;
  font-size: var(--名字大小);
  font-weight: normal;
  color: #004030;
  position: absolute;
  top: -185px;
  left: 32%;
  transform: translateX(-50%) !important;
  letter-spacing: 2px;
  width: auto;
  max-width: 300px;
  white-space: normal;
  word-break: break-all;
  text-align: center; 
  z-index: 9;
  opacity: 1 !important;
  font-family: "XuanZongTi" !important;
  height: auto;
  min-height: initial;
  max-height: initial;
  box-sizing: border-box;
  margin: 0;
  display: block;
  transform-origin: center;
}

.mes .name_text::after { 
  content: var(--诗句);
  position: absolute;
  left: 100%;
  top: 50px;
  margin-left: var(--间距);   
  font-size: var(--诗句大小);
  font-weight: normal;
  color: #004030;
  white-space: nowrap; 
  z-index: 999;
}
.mes .timestamp {
    font-size: 13px;
    font-weight: 600;
    color: #004030;
    position: absolute;
    top:-36px ;
    left: 52vw;
    display: flex;
    transform-origin: center;
    transform:none!important;
    text-align: center;
   opacity:0.4!important;
    z-index:99;
    font-family: "Clear Han Serif" !important;
}

/*操作按钮*/
.mes_buttons{
position:absolute;
top: -5px; 
left: 0;
z-index:999;
width:100%;
}

/* 编辑按钮图标替换 */
.mes_button.mes_edit.fa-pencil.interactable {
    position: relative;    
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 15px; 
    color: #688770;
    border: none;
    background: transparent;
    cursor: pointer;
    z-index: 99;    
    opacity:1!important;
}

/*编辑菜单位置调整  */
/*二改自易碎蝶老师*/
.mes_edit_buttons {
    box-shadow: none !important;
    filter: none !important;
}
.mes_edit_buttons .menu_button {
    cursor: pointer;
    transition: opacity 0.2s ease-in-out;
    color: #1e4d1e !important;
    background-color: #fff !important;
    box-shadow: none !important;
    filter: none !important;
}
.mes:hover .mes_edit_buttons,
.mes.selected .mes_edit_buttons {
    opacity: 1 !important;
    pointer-events: auto !important;
}
.mes_button, .extraMesButtons>div {
cursor: pointer;
    transition: opacity 0.2s ease-in-out;
    filter: drop-shadow(0px 0px 0px #ffffff) !important;   
opacity: 1 !important;    
}

/* 消息操作按钮图标替换 */
.mes_button.extraMesButtonsHint.fa-ellipsis.interactable {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 15px; 
    color: #688770;
    border: none;
    background: transparent;
    cursor: pointer;
    z-index: 9999;
}

.mes_button.favorite-toggle-icon.interactable {
    position: relative;
    margin-right:10px; 
    color: #688770 !important;
    opacity:1!important; 
}

/* 源自12老师 */
.mes_text br:first-child,
.mes_text br:first-child + br {
    display: none;
}

.mes_text {
    width:100%;
    padding: 0px 0px 20px 4px !important;
    margin-top:0px;
    z-index: 999;
    flex: 1;
    line-height: 1.8;
}
.mes_text p {
    margin-bottom: 1em!important;    
}
.mes_text q {  
  text-shadow: 0 0 8px rgba(61, 142, 134, 0.6) !important;
}

/* 代码块样式 */
.mes_text code {
    display: inline-block;
    background-color: #fcfefe !important;
    padding: 8px 8px;
    margin: 5px 8px 5px 0 !important;
    color: #3a6351 !important;
    border: 0.9px solid #a8e6cf !important;
    border-radius: 4px !important;
    letter-spacing: 0.3px !important;
    word-spacing: 1px !important;
    line-height: 1.4 !important;
    font-size: 1em !important;
    box-shadow: 0 0 4px rgba(168, 230, 207, 0.3) !important;
}
.mes_text blockquote {   
    margin: 16px 8px 20px 0 !important;
    padding: 20px 24px !important;  
    position: relative;
    background: rgba(255, 255, 255, 0.85) !important;
    border: 1px solid rgba(168, 230, 207, 0.3) !important;
    border-radius: 14px !important;
    color: #4a7c68 !important;
    box-shadow: 0 8px 30px rgba(168, 230, 207, 0.08) !important;
    backdrop-filter: blur(4px) !important;
    line-height: 1.6 !important;
    font-family: "Clear Han Serif";  
}

/*思维链 */
.mes_reasoning_header {
    position: relative !important;
    top: -5px !important;
    left: 8px !important;
    transform: none !important;
    transition: none !important;
    animation: none !important;
    width: 90% !important;
    height: 10px !important;
    color: transparent !important;
    font-size: 1em !important;
    background-color:rgba(225,225,225,0) !important;
    background-image: none !important;
    background-size: cover !important;
    background-position: center center !important;
}

.mes_reasoning_header.flex-container::before {
    content: "春山苍苍，春水漾漾。";
    position: absolute !important;
    top: 50% !important;
    left: 53% !important;
    transform: translate(-50%, -50%) !important;
    color: #91ae84 !important;  
    font-size: 1em !important;
    font-weight: 600 !important;
    letter-spacing: 1px !important;
    text-transform: uppercase !important;
    white-space: nowrap !important;
    z-index: 2 !important;
}
.mes_reasoning{
position:relative;
top:20px;}

/* ==消息元数据 == */
/* 定义统一偏移变量 */
.mesIDDisplay,
.tokenCounterDisplay,
.mes_timer {
    position: absolute !important;
    display: inline-block;    
    font-weight: 500;    
    font-family: "Clear Han Serif";
}
.mesIDDisplay { 
    left:var(--楼层水平方向);
    top:var(--楼层垂直方向);
   font-weight: normal;
   color: #004030;   
   font-size: 14px!important;
}
.mesIDDisplay::before {
    content: "";
    position: absolute;
    top: -9px;
    left: -8px;
    width: calc(190% + 32px);
    height: calc(190%);
    background-image: url("https://iili.io/Bftmhns.png");
    background-size: contain;
    background-repeat: no-repeat;
    z-index: -1;
    pointer-events: none;
    opacity:0.9;
}
.tokenCounterDisplay { 
    left:var(--token水平方向);
    top:var(--token垂直方向);
    font-size: 14px!important;
    color:#49864D;   
}
.mes_timer { 
    left: var(--时间水平方向);
    top:var(--时间垂直方向);
    font-size: 14px!important;
    color:#49864D;
}
.mesIDDisplay:empty,
.tokenCounterDisplay:empty,
.mes_timer:empty {
    display: none !important;
}
/* 左边按钮 */
.swipe_left.fa-solid.fa-chevron-left.interactable::before {
    content: "上 叶";
    position: absolute;
    font-family: "平方赖江湖飞扬体";
    color: #004030;
    opacity: 1;
    white-space: nowrap;
    left:-10px;
    top:20px;
}
/* 右边按钮 */
.swipe_right.fa-solid.fa-chevron-right.interactable::before {
    content: "下 叶";
    position: absolute;
    font-family: "平方赖江湖飞扬体";
    right:0%;
    color: #004030;
    opacity: 1;
    white-space: nowrap;
    top:20px;  
}
.swipes-counter {
  position: flex;
  font-size:15px;
  top: -3px;
  right: 40vw !important;
  font-family:"平方赖江湖飞扬体";
  opacity: 1!important;
  color: #688770 !important;
  white-space: nowrap !important;
  z-index: 99;
  position: relative; 
  display: inline-flex; 
  align-items: center;  
  transform:scale(1.5);
}
.swipes-counter:empty {
     display: none;
 }

/* ==顶部栏== */
#top-bar {
    background-color: rgba(149, 193, 148, 0.1);
    background-position: center;
    background-repeat: no-repeat;
    box-shadow: none;  
    position: relative;
    height: 28px;
    width: 100%;
    /* 毛玻璃效果 */
    backdrop-filter: blur(10px) !important;
    -webkit-backdrop-filter: blur(10px) !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.2) !important;
}
/* 顶部图标通用样式 */
#top-settings-holder .drawer-icon {
    color: #fff;
    display: block;
    opacity: 1 !important;
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
    transition: all 0.3s ease-in-out;
    transform: scale(0.56);
}
#top-settings-holder .drawer-icon:focus {
    color: #4A9782 !important;
}
#top-settings-holder{
position:relative;
top:-30px;}
/* ==底部输入栏== */
#send_form {
    position: relative;
    width: 100%;
    height:100%;    
    background-image: url('https://iili.io/B2baFNs.jpg');
    background-color: rgba(225,225,225,0);
    background-blend-mode: overlay;
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    transition: all 0.3s ease;     
}
#nonQRFormItems {
    display: flex;
    align-items: center;
    justify-content: flex-start; 
    transform: none !important;
}
/* 底部按钮基础 */
#options_button.fa-bars,
#extensionsMenuButton.fa-magic-wand-sparkles,
#send_but.fa-paper-plane,
#mes_stop,
#quick-reply-rocket-button {
    position: relative;
    font-size: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    clip-path: none;
    border: none;
    background: transparent;
    cursor: pointer;
    top:-2px;
}
#options_button.fa-bars::before,
#extensionsMenuButton.fa-magic-wand-sparkles::before,
#send_but.fa-paper-plane::before,
#mes_stop::before,
#quick-reply-rocket-button::before {
    content: '' !important;
    display: block;
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
    font-size: 0;
}
/* 选项按钮 */
#options_button.fa-bars::before {
    background-image: url('https://iili.io/BfbZDGf.png');    
   width: 25px !important;
    height: 25px !important;
}
/* 扩展按钮 */
#extensionsMenuButton.fa-magic-wand-sparkles::before {
    background-image: url('https://iili.io/BfbZDGf.png');
    position: absolute;
    width: 25px !important;
    height: 25px !important;
    flex-shrink: 0;   
}
/* 发送按钮 */
#send_but.fa-paper-plane::before {
    background-image: url('https://iili.io/B3OASfV.png');
    width: 32px !important;
    height: 32px !important;
}
/* 停止按钮 */
#mes_stop::before {
    background-image: url('https://iili.io/B3Hb4un.png') !important;
    width:32px !important;
    height: 32px !important;    
}
#quick-reply-rocket-button::before {
   content: "";    
   width: 25px; 
   height: 25px;
   background-image: url('https://iili.io/BfbZDGf.png');
 }

/* 输入框 */
#send_textarea {
    position: relative;
    clip-path: none;
    flex-shrink: 0;
    box-sizing: border-box;
    outline: none;
    padding-right: 0px !important;
    vertical-align: top;
    border: none !important;
    box-shadow: none !important;
    text-shadow: none !important;
   color:#004030;
   font-size: 14px;
}
#send_textarea::placeholder {
    color: transparent !important;
}
#leftSendForm {
flex-shrink: 0; 
display: flex;
align-items: center;
gap: 5px; 
}
#rightSendForm {
flex-shrink: 0; 
display: flex;
align-items: center;
gap: 5px; 
margin-right:6px;
}



/* == UI 组件 == */
/* 滑块 (Range Input) */
input[type="range"],
input[type="range"]:disabled {
    -webkit-appearance: none;
    filter: none;
    box-shadow: none!important;    
    background: linear-gradient(to right, #fff, #6a8d6d)!important;
    background-size: auto 100%;
    height: 4px;
    border: none!important;
    border-radius: 0!important;
}
input[type="range"]::-webkit-slider-thumb {    
    width: 20px;
    height: 20px;
    /* 重置浏览器默认样式 */
    -webkit-appearance: none;
    appearance: none;
    background-image: url('https://iili.io/BfbZDGf.png');
    background-size: contain; 
    background-position: center;
    background-repeat: no-repeat;
    background-color: transparent;
    border: none;
    outline: none;
    box-shadow: none;  
    cursor: pointer;
    overflow: visible;
}

input:not(input[type="range"], input[type='checkbox']) {
  background: url("https://iili.io/BCJ7T1j.png") no-repeat center center;
  background-size: 100% 100%; 
  border: none;
  border-radius: 0;
  top:2px;
  position:relative;
}

/* 复选框 */
/*换图根据食南瓜者老师的调整的*/
input[type="checkbox"] {
    background: #fff;
    border: none;
    box-shadow: none;
  border-radius: 50%;
    width: 2.5em;
    height: 2.5em;   
    transform: rotate(-30deg);
   appearance: none;
   -webkit-appearance: none;
   background: url('https://iili.io/BCn5g2I.png');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center center;
    box-shadow: none;
    border: none !important;
    outline: none;
    position:relative;
}
input[type="checkbox"]:checked {
    background: url('https://iili.io/BCnaBmF.png');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center center;
    box-shadow: none;
    border: none !important;
    outline: none;
    position:relative;  
    opacity:1!important;
    transform: rotate(50deg)!important;
}
input[type="checkbox"]::before {
    box-shadow: none;
}


/* ==设置面板与扩展 == */
/* 抽屉头部与标题 */
.inline-drawer-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader,
.select2-selection.select2-selection--multiple, 
#image_overswipe,
.J-paginationjs-size-select {
    color:#004030!important;
    background: url("https://iili.io/BCFO6Eg.png") no-repeat center center;
  background-size: 100% 100%; 
  border: none;
  border-radius: 0!important;
    margin-bottom:10px;
    transition: all 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
    position: relative;
    right: -2px;
    overflow: hidden;   
}

.inline-drawer-icon {
  box-shadow: none !important;
  filter: none !important;  
  position: relative;
  width: 25px ;
  height: 25px;
}

 .inline-drawer-icon::before {
